import {Sandbox,BLOCKS,RECIPES,HOTBAR,SAVE_PREFIX,SIZE,HEIGHT} from './sandbox-core.js';
import {feedAnimal} from './sandbox-animals.js';
import {SandboxWorld} from './sandbox-world.js';
import {showcase} from './sandbox-showcase.js';

const $=id=>document.getElementById(id),canvas=$('world'),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
let storage;try{storage=localStorage;}catch{}
let world=new Sandbox('creative'),homeWorld=showcase(),render;
try{render=new SandboxWorld(canvas);render.setWorld(world);}catch(error){$('loading').innerHTML='图形画面未能启动。<br>请使用启用硬件加速的 Chrome 或 Edge 刷新。';throw error;}
let active=false,paused=false,view='third',flying=false,yaw=0,pitch=-.14,vy=0,grounded=false,selected=0,slots=[...HOTBAR],left=false,mineElapsed=0,mineKey='',target=null,last=performance.now(),saveClock=0,hudClock=0,targetClock=0,attackClock=0,toastTimer,lookDrag=false;
const keys=new Set(),moveTouch={x:0,y:0},lookTouch={x:0,y:0};
try{view=storage?.getItem('mosslight-sandbox-view')==='first'?'first':'third';}catch{}
function toast(message){if(!message)return;$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);const feedback=$('feedback');if(feedback)feedback.textContent=message;}
function feedback(){if(world.message){toast(world.message);world.message='';}}
function save(){if(!active)return;try{storage?.setItem(SAVE_PREFIX+world.mode,JSON.stringify(world.snapshot()));}catch{if(!save.warned){save.warned=true;toast('浏览器存储已满，请在菜单中导出世界备份。');}}}
function clearInput(){keys.clear();left=false;mineElapsed=0;mineKey='';moveTouch.x=moveTouch.y=lookTouch.x=lookTouch.y=0;document.querySelectorAll('.touch-stick i').forEach(i=>i.style.transform='');}
function release(){if(document.pointerLockElement===canvas)document.exitPointerLock();}
function showHome(){save();render.setWorld(homeWorld);active=false;paused=false;release();clearInput();$('home').hidden=false;$('hud').hidden=true;$('overlay').hidden=true;for(const mode of ['creative','survival']){let exists=false;try{exists=!!storage?.getItem(SAVE_PREFIX+mode);}catch{}$(mode+'Label').textContent=exists?'继续这个世界 ↗':mode==='creative'?'进入创造世界 ↗':'进入生存世界 ↗';}}
function start(mode){save();let saved=null;try{const text=storage?.getItem(SAVE_PREFIX+mode);if(text)saved=JSON.parse(text);}catch{toast('原存档无法读取，已保留原数据。请先选择另一模式，或从菜单导入有效备份。');return;}
  world=new Sandbox(mode,saved);render.setWorld(world);active=true;paused=false;flying=mode==='creative';vy=0;yaw=0;pitch=-.14;selected=0;slots=[...HOTBAR];clearInput();$('home').hidden=true;$('overlay').hidden=true;$('hud').hidden=false;syncButtons();updateHud();canvas.focus();capture();toast(mode==='creative'?'方块无限供应。F 飞行，B 打开方块库；按住左键拆除，右键沿选中面搭建。':'空手砍树 → B 制作木板和木镐 → 采石 → 放工作台 → 盖房子。采树叶可获得浆果。');}
function syncButtons(){$('view').textContent='V '+(view==='first'?'第一人称':'第三人称');$('flight').hidden=world.mode!=='creative';$('flight').textContent=flying?'F 飞行中':'F 步行';$('touchDown').hidden=!flying;$('modeName').textContent=world.mode==='creative'?'自由创造 / 无限方块':'生存建造 / 从零开始';$('craftButton').textContent=world.mode==='creative'?'B 方块库':'B 制作';}
function toggleView(){view=view==='first'?'third':'first';try{storage?.setItem('mosslight-sandbox-view',view);}catch{}syncButtons();}
function hotbar(){const unlimited=world.mode==='creative';$('selectedBlock').textContent=BLOCKS[slots[selected]].name+' · '+(unlimited?'无限':world.inv[slots[selected]]||0);render.heldBlock.material.color.set(BLOCKS[slots[selected]].color);$('hotbar').innerHTML=slots.map((id,i)=>`<button data-slot="${i}" class="${i===selected?'selected':''}" aria-label="选择${BLOCKS[id].name}" style="--color:${BLOCKS[id].color}"><em>${i+1}</em><i></i><strong>${unlimited?'∞':world.inv[id]||0}</strong><small>${BLOCKS[id].name}</small></button>`).join('');document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.slot);hotbar();});}
function updateHud(){const p=world.player;$('dayText').textContent=`第 ${Math.floor(world.day/360)+1} 天 · ${world.night()?'夜晚 / 注意荒野生物':'白昼'} · ${Math.floor(p.x)}, ${Math.floor(p.y)}, ${Math.floor(p.z)}`;$('health').textContent=world.mode==='creative'?'✦ 不受伤害':`生命 ${Math.ceil(p.hp)} / 100`;$('food').textContent=world.mode==='creative'?'无限材料':`饱食 ${Math.ceil(p.food)} · 浆果 ${world.inv.berry||0}（H 食用）`;
  const tasks=world.mode==='creative'?[[world.stats.placed>=1,'放下你的第一块方块'],[world.stats.placed>=20,'搭一面墙，再加上屋顶'],[world.near(9,10),'用灯方块点亮家园']]:[[world.stats.wood>=3,'砍树，收集 3 块原木'],[world.tools.pick,'B 制作木板与木镐'],[(world.inv[3]||0)>0||world.tools.axe,'用木镐开采石头'],[!!world.near(10,10),'制作并放置工作台'],[!!world.near(11,10),'制作床，按 E 设置重生点']];$('goalList').innerHTML=tasks.map(([done,label])=>`<div class="${done?'done':''}">${done?'✓':'○'} ${label}</div>`).join('');hotbar();}
function panel(title,html){paused=true;release();clearInput();$('panelTitle').textContent=title;$('panelContent').innerHTML=html+'<p id="feedback" role="status"></p>';$('overlay').hidden=false;$('hud').inert=true;requestAnimationFrame(()=>$('panelContent').querySelector('button')?.focus());}
function closePanel(){paused=false;$('overlay').hidden=true;$('hud').inert=false;clearInput();canvas.focus();capture();}
function chooseBlock(id){slots[selected]=id;closePanel();hotbar();toast('已装备 '+BLOCKS[id].name+'，右键放置。');}
function library(){if(!active)return;const creative=world.mode==='creative';panel(creative?'方块库 · 放手去创造':'背包与工作台',`<p>${creative?'点击方块替换当前快捷栏。无限数量，可自由飞行，搭建最高 22 层。':'点击材料放入当前快捷栏。左键采集、右键放置；配方会消耗材料。带有“工作台”的配方需靠近自己放置的工作台。'}</p><div class="palette">${Object.entries(BLOCKS).filter(([id])=>id!=='15').map(([id,b])=>`<button data-block="${id}" style="--color:${b.color}"><i class="block-icon"></i>${b.name}<small>${creative?'无限':world.inv[id]||0}</small></button>`).join('')}</div>${creative?'':`<h3>制作</h3><p>木镐：${world.tools.pick?'已拥有':'未制作'} · 石斧：${world.tools.axe?'已拥有':'未制作'} · 浆果：${world.inv.berry||0}（行动中 H 食用）</p><div class="recipes">${RECIPES.map(r=>`<article class="recipe"><b>${r.name}</b><p>${Object.entries(r.cost).map(([id,n])=>BLOCKS[id].name+' '+(world.inv[id]||0)+' / '+n).join(' · ')}${r.table?'<br>需要附近的工作台':''}</p><button data-recipe="${r.id}" ${r.upgrade&&world.tools[r.upgrade]?'disabled':''}>${r.upgrade&&world.tools[r.upgrade]?'已制作':'制作'}</button></article>`).join('')}</div>`}`);
  document.querySelectorAll('[data-block]').forEach(b=>b.onclick=()=>chooseBlock(Number(b.dataset.block)));document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>{const ok=world.craft(b.dataset.recipe),message=world.message;world.message='';if(ok){save();library();}toast(message);});}
function menu(){if(!active)return;panel('我的方块世界',`<p>方块改动、背包、工具、时间与所在位置会自动保存。创造和生存分别存档，切换模式后仍可回来继续建设。</p><button class="menu-button" id="resume">继续建设</button><button class="menu-button" id="export">导出这个世界的备份</button><button class="menu-button" id="import">导入世界备份</button><input type="file" id="worldFile" accept=".json,application/json" hidden><button class="menu-button" id="homeButton">保存并返回模式选择</button><p>点击画面捕获鼠标，左右转向、上下观察。Esc 释放鼠标并暂停。WASD 移动，空格跳跃，左键按住采集，右键放置；数字键 / 滚轮选方块，B 方块库或制作，V 切换第一 / 第三人称。创造 F 飞行，空格上升、Shift 下降。生存 E 使用床，H 吃浆果。鼠标无需按键即可环视；浏览器不支持捕获时，移入画面也可自由转向。按 E 可喂食附近准星指向的牛羊。</p>`);
  $('resume').onclick=closePanel;$('homeButton').onclick=()=>{$('hud').inert=false;showHome();};$('export').onclick=()=>{save();const url=URL.createObjectURL(new Blob([JSON.stringify(world.snapshot())],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='苔光_'+(world.mode==='creative'?'创造':'生存')+'_世界备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);};$('import').onclick=()=>$('worldFile').click();$('worldFile').onchange=async e=>{try{const file=e.target.files?.[0];if(!file)return;if(file.size>3e6)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!['creative','survival'].includes(data.mode)||!Array.isArray(data.edits)||!data.player)throw Error();panel('恢复这份世界？',`<p>将替换${data.mode==='creative'?'创造':'生存'}世界。建议先导出原世界备份。</p><button id="confirmImport" class="menu-button">确认恢复</button><button id="cancelImport" class="menu-button">取消，保留原世界</button>`);$('cancelImport').onclick=menu;$('confirmImport').onclick=()=>{const next=new Sandbox(data.mode,data);try{storage?.setItem(SAVE_PREFIX+data.mode,JSON.stringify(next.snapshot()));}catch{toast('备份无法保存，原世界仍保留。');return;}active=false;start(data.mode);$('hud').inert=false;toast('世界已恢复。');};}catch{toast('无法读取世界备份，当前世界未改变。');}};
}
function hitTarget(){target=render.target();const animal=render.animalTarget();render.selection(animal?null:target);if(animal){$('target').textContent=(animal.species==='cow'?'奶牛':'绵羊')+' · 走近后 E 喂食浆果';return;}$('target').textContent=target?`${BLOCKS[target.id].name} · ${world.mode==='survival'&&BLOCKS[target.id].pick&&!world.tools.pick?'需要木镐':'左键采集 / 右键放置'}`:'';}
function place(){if(!active||paused)return;hitTarget();if(!target){toast('先瞄准 7 格以内的方块表面。');return;}const t=target,n=t.normal;if(world.place(t.x+n.x,t.y+n.y,t.z+n.z,slots[selected])){mineElapsed=0;save();updateHud();}feedback();}
function interact(){const animal=render.animalTarget();if(animal)feedAnimal(world,animal.id);else if(world.near(11))world.sleep();else if(world.near(10))library();else world.message='工作台可以打开制作，床可以设置重生点并跳过夜晚。';feedback();save();}
function capture(){if(!active||paused||matchMedia('(pointer:coarse)').matches||document.pointerLockElement===canvas)return;try{canvas.requestPointerLock()?.catch(()=>toast('已启用自由环视：鼠标移入画面即可转向，无需按住按键。'));}catch{toast('鼠标移入画面即可自由环视，Esc 暂停后可操作菜单。');}}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>start(b.dataset.mode));$('view').onclick=toggleView;$('flight').onclick=()=>{flying=!flying;vy=0;syncButtons();};$('craftButton').onclick=library;$('pause').onclick=menu;$('closePanel').onclick=closePanel;
window.addEventListener('keydown',e=>{if(!active)return;if(e.code==='Escape'){e.preventDefault();if(paused)closePanel();else menu();return;}if(paused)return;if(['Tab','Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(/^Digit[1-9]$/.test(e.code)){selected=Number(e.code.slice(-1))-1;hotbar();}if(e.code==='KeyV')toggleView();if(e.code==='KeyB'||e.code==='Tab')library();if(e.code==='KeyF'&&world.mode==='creative'){flying=!flying;vy=0;syncButtons();}if(e.code==='KeyH'){world.eat();feedback();updateHud();}if(e.code==='KeyE')interact();});window.addEventListener('keyup',e=>keys.delete(e.code));
canvas.addEventListener('pointerdown',e=>{if(!active||paused||e.pointerType==='touch')return;if(e.button===1||e.altKey){lookDrag=true;return;}capture();if(e.button===0)left=true;if(e.button===2)place();});window.addEventListener('pointerup',()=>{left=false;lookDrag=false;mineElapsed=0;});canvas.addEventListener('pointermove',e=>{if(!active||paused)return;if(e.pointerType==='touch')return;if(document.pointerLockElement===canvas||e.target===canvas||lookDrag||e.altKey){yaw-=e.movementX*.0028;pitch=clamp(pitch-e.movementY*.0028,-1.4,1.35);}});canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('wheel',e=>{if(!active||paused)return;e.preventDefault();selected=(selected+Math.sign(e.deltaY)+9)%9;hotbar();},{passive:false});document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&active&&!paused)menu();});
function stick(id,out){const base=$(id),knob=base.querySelector('i');let pointer=null;const change=e=>{const r=base.getBoundingClientRect(),dx=e.clientX-r.x-r.width/2,dy=e.clientY-r.y-r.height/2,n=Math.max(1,Math.hypot(dx,dy)/(r.width*.32));out.x=dx/n/(r.width*.32);out.y=dy/n/(r.width*.32);knob.style.transform=`translate(${dx/n}px,${dy/n}px)`;};base.onpointerdown=e=>{if(paused)return;pointer=e.pointerId;base.setPointerCapture(pointer);change(e);};base.onpointermove=e=>{if(pointer===e.pointerId)change(e);};for(const event of ['pointerup','pointercancel','lostpointercapture'])base.addEventListener(event,e=>{if(pointer!==e.pointerId)return;pointer=null;out.x=out.y=0;knob.style.transform='';});}
stick('move',moveTouch);stick('look',lookTouch);function holdButton(id,down,up){const b=$(id);b.onpointerdown=e=>{if(paused)return;e.preventDefault();b.setPointerCapture(e.pointerId);down();};for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,up);}
holdButton('touchMine',()=>left=true,()=>left=false);$('touchPlace').onclick=place;$('touchUse').onclick=interact;holdButton('touchJump',()=>keys.add('Space'),()=>keys.delete('Space'));holdButton('touchDown',()=>keys.add('ShiftLeft'),()=>keys.delete('ShiftLeft'));
window.addEventListener('resize',()=>render.resize());window.addEventListener('blur',()=>{clearInput();if(active&&!paused)menu();});document.addEventListener('visibilitychange',()=>{if(document.hidden){save();clearInput();if(active&&!paused)menu();}});window.addEventListener('pagehide',save);
function physics(dt){const p=world.player;let sx=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+moveTouch.x,sy=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-moveTouch.y;const n=Math.max(1,Math.hypot(sx,sy));sx/=n;sy/=n;const speed=!flying&&keys.has('ShiftLeft')?6:4.3,dx=(Math.cos(yaw)*sx-Math.sin(yaw)*sy)*speed*dt,dz=(-Math.sin(yaw)*sx-Math.cos(yaw)*sy)*speed*dt;const x=clamp(p.x+dx,.3,SIZE-.3),z=clamp(p.z+dz,.3,SIZE-.3);if(!world.collides(x,p.y,p.z))p.x=x;if(!world.collides(p.x,p.y,z))p.z=z;
  grounded=world.collides(p.x,p.y-.07,p.z);if(flying){vy=0;const dy=((keys.has('Space')?1:0)-(keys.has('ShiftLeft')||keys.has('ShiftRight')?1:0))*5*dt;if(!world.collides(p.x,p.y+dy,p.z))p.y=clamp(p.y+dy,1,HEIGHT-1.8);}else{if(grounded&&vy<0)vy=0;if(grounded&&keys.has('Space'))vy=8;vy=Math.max(-18,vy-22*dt);const next=p.y+vy*dt;if(!world.collides(p.x,next,p.z))p.y=next;else{if(vy<0){const old=p.y;let low=next,high=old;for(let i=0;i<8;i++){const mid=(low+high)/2;if(world.collides(p.x,mid,p.z))low=mid;else high=mid;}p.y=high;}vy=0;}if(p.y<.3){world.respawn();vy=0;}}
  return Math.hypot(sx,sy)*speed;
}
function wildlife(dt){if(world.mode!=='survival')return;world.mobClock+=dt;const p=world.player;if(!world.night()){world.mobs=[];return;}if(world.mobClock>12&&world.mobs.length<4){world.mobClock=0;const angle=world.day*2.3,x=clamp(p.x+Math.sin(angle)*9,2,45),z=clamp(p.z+Math.cos(angle)*9,2,45),y=world.surface(Math.floor(x),Math.floor(z));if(y<10)world.mobs.push({x,y,z,hp:40,cooldown:1,angle:0});}for(const m of world.mobs){const dx=p.x-m.x,dz=p.z-m.z,d=Math.hypot(dx,dz)||1;m.angle=Math.atan2(dx,dz)+Math.PI;m.cooldown-=dt;const nx=m.x+dx/d*dt*1.5,nz=m.z+dz/d*dt*1.5;if(!world.collides(nx,m.y,m.z))m.x=nx;if(!world.collides(m.x,m.y,nz))m.z=nz;if(!world.collides(m.x,m.y-.1,m.z))m.y-=dt*8;if(d<1.35&&Math.abs(m.y-p.y)<1.5&&m.cooldown<=0){p.hp=Math.max(0,p.hp-8);m.cooldown=1;toast('荒野生物靠近了！左键近战，或回到墙内避险。');}}world.mobs=world.mobs.filter(m=>m.hp>0);}
function mine(dt){attackClock-=dt;if(left&&render.animalTarget()){$('mineProgress').hidden=true;mineElapsed=0;return;}if(!left){mineElapsed=0;mineKey='';$('mineProgress').hidden=true;return;}if(attackClock<=0){const p=world.player,mob=world.mobs.find(m=>Math.hypot(m.x-p.x,m.z-p.z)<2.5&&Math.abs(m.y-p.y)<2&&((m.x-p.x)*-Math.sin(yaw)+(m.z-p.z)*-Math.cos(yaw))>0);if(mob){mob.hp-=world.tools.axe?35:12;attackClock=.45;toast(mob.hp<=0?'击退了荒野生物。':'近战命中');return;}}
  if(!target)return;const key=target.x+','+target.y+','+target.z;if(key!==mineKey){mineKey=key;mineElapsed=0;}const duration=world.mineTime(target.id);if(!Number.isFinite(duration)){$('mineProgress').hidden=true;if(world.message)feedback();return;}mineElapsed+=dt;$('mineProgress').hidden=false;$('mineProgress').firstElementChild.style.width=Math.min(100,mineElapsed/duration*100)+'%';if(mineElapsed>=duration){if(world.breakBlock(target.x,target.y,target.z)){mineElapsed=0;hitTarget();hudClock=1;}feedback();}}
let speed=0,frames=0;function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,Math.max(0,(now-last)/1000));last=now;if(active&&!paused){yaw-=lookTouch.x*dt*2;pitch=clamp(pitch-lookTouch.y*dt*1.6,-1.4,1.35);speed=physics(dt);world.tick(dt);wildlife(dt);feedback();saveClock+=dt;hudClock+=dt;targetClock+=dt;if(saveClock>3){saveClock=0;save();}if(hudClock>.3){hudClock=0;updateHud();}}
  if(!paused){render.update(active?world.player:homeWorld.player,yaw,pitch,active?view:'third',dt,active?speed:0);render.hand.visible=active&&view==='first';if(!active){render.camera.position.set(43,13,49);render.camera.lookAt(23,5.8,39);render.camera.updateMatrixWorld();}if(active){if(targetClock>.06){targetClock=0;hitTarget();}mine(dt);}else render.outline.visible=false;render.render();}frames++;}
showHome();$('loading').hidden=true;window.sandboxReady=true;requestAnimationFrame(frame);
// 提供只读诊断，便于校验真实操作造成的世界改动。
window.sandbox={state:()=>({active,paused,mode:world.mode,view,yaw,pitch,flying,selected,slots:[...slots],target:target?{...target}:null,player:{...world.player},inventory:{...world.inv},tools:{...world.tools},stats:{...world.stats},edits:world.edits.size,day:world.day,mouseCaptured:document.pointerLockElement===canvas,animals:world.animals.map(a=>({id:a.id,species:a.species,x:a.x,y:a.y,z:a.z,moving:a.moving,grazing:a.grazing,follow:a.follow})),diagnostics:render.metrics()}),block:(x,y,z)=>world.get(x,y,z),save:()=>world.snapshot()};





